    ok("!! meanPower is the mean of dark and lit mean powers to the last digit (5 kW; dark 6 and lit 4 gives 5; plus 1 kW gives 6)", near(X.meanPower(mkAu(), "c02"), 5, 1e-12) && (() => { const x = mkAu(); for (const q of x.dark.c02) q.watts = 6000; for (const q of x.lit.c02) q.watts = 4000; return near(X.meanPower(x, "c02"), 5, 1e-12); })() && (() => { const x = mkAu(); watt(x, "c02", 1000); return near(X.meanPower(x, "c02"), 6, 1e-12); })());
    ok("!! penMean is the mean of the penalised priced scores at the price (default 0.04): a c02 of 5 kW at 0.04 is its mean of dark and lit scores minus 0.20, at 0.08 minus 0.40, at 0.02 minus 0.10", (() => { const x = mkAu(), m = (X.scoreMean(x, "c02", "dark") + X.scoreMean(x, "c02", "lit")) / 2; return near(X.penMean(x, "c02"), m - 0.2, 1e-9) && near(X.penMean(x, "c02", 0.08), m - 0.4, 1e-9) && near(X.penMean(x, "c02", 0.02), m - 0.1, 1e-9); })());
